sql_query:
SELECT "Control regimen"
FROM clinical_trials
WHERE "Cancer type" = 'Bladder' AND "Control arm" = 'Chemo' AND "Included in MA" = 'Yes' AND "Trial phase" = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Control regimen" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Bladder' AND "Control arm" = 'Chemo' AND "Included in MA" = 'Yes' AND "Trial phase" = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_control_drugs(source_value) AS "control_drugs"
FROM base;
